// TH14 v1.00b Stage 6 BossCard1 -- 小弾「小人の道」/「小人の茨道」
// Source: st06bs.ecl.txt:724-767 (entry), 769-863 (BossCard1_at).
// TH14 synthetic bullet catalogue (bullet-types.md): native type0-23 -> same slot.
const TH14_PELLET2: int = 368;          // native type 1
const TH14_INVERT_POPCORN: int = 384;   // native type 2

const TIME_LIMIT: int = 3124;           // 120 opening + 3000 window + 4 startup
const OPENING_BUFFER: int = 120;
const SOURCE_LIMIT: int = 2700;         // source slot0 timeout (timerReset at 727)

// BossCard1_at source frame 150 spawn; first task step is source frame 151.
// Stop firing when the source interrupt would fire at source 2700.
const HELPER_STOP: int = SOURCE_LIMIT - 151;  // 2549 helper frames

// Emitter 1 (native type2/color10) EX chain, birth ANIM/SPEEDUP omitted:
//   WAIT 60; VELTIME 40 -> speed 0 keep angle; WAIT 60;
//   VELTIME 40 -> speed 1.0 toward player (s=999).
xformdef TH14_S6_B2_MINION {
    @60 add_speed(0fx);                                  // WAIT 60
    @40 step_speed(0fx, 40);                             // VELTIME 40, linear to 0
    @60 add_speed(0fx);                                  // WAIT 60
    set_angle(at_effect(atan2($player_y - $self_y, $player_x - $self_x)));
    @40 step_speed(1fx, 40);                             // VELTIME 40, linear to 1
}

// Source BossCard1_at(): the two emitters are configured once, then a wave is
// fired every F frames with a random-walking base drift D.
async sub boss_card1_at() {
    var rank: int = global(GVAR_RANK);

    // diffI($F,76,76,60,60); diffI($G,50,30,25,22)  (source 794-795)
    var F: int = 76;
    var G: int = 50;
    if rank == RANK_NORMAL {
        G = 30;
    } else if rank == RANK_HARD {
        F = 60; G = 25;
    } else if rank == RANK_LUNATIC {
        F = 60; G = 22;
    }

    // !E 1.5f; !N 1.5f; !H 1.5f; !LO 1.6f (source 800-808, 831-839)
    var spd: fx = 1.5fx;
    if rank == RANK_LUNATIC { spd = 1.6fx; }

    // !E 0.048332f; !N/H/LO 0.048707f -> BAM (source 810-818, 821-829)
    var dstep: int = 508;
    if rank == RANK_EASY { dstep = 504; }

    // %D = %RANDF2 * 0.17453292f  (signed 10deg, source 796)
    var D: int = rand(3641) - 1820;
    var t: int = 0;

    // etNew(0): aimed mode 0/1 fixed fan, 128 ways, native type1 color6.
    sh_reset(0);
    sh_sprite(0, TH14_PELLET2, 6);
    sh_aim(0, 0);
    sh_ring(0, 0);                 // fan: base + i*step - (n-1)*step/2
    sh_count(0, 128, 1);

    // etNew(1): one bullet down through the fan gap, native type2 color10.
    sh_reset(1);
    sh_sprite(1, TH14_INVERT_POPCORN, 10);
    sh_aim(1, 0);
    sh_ring(1, 0);
    sh_count(1, 1, 1);
    sh_xform(1, TH14_S6_B2_MINION);

    loop {
        if t >= HELPER_STOP { return; }

        // etSpeed + etAngle + etOn for both emitters (source 800-841).
        // Fan base = %D + -pi/2; minion base = +pi/2 + %D.
        sh_angle(0, (D - 16384) as angle, dstep as angle);
        sh_speed(0, spd, 0fx);
        sh_fire(0);
        sh_angle(1, (16384 + D) as angle, 0deg);
        sh_speed(1, spd, 0fx);
        sh_fire(1);

        // unless ($F >= $G) skip; $F = $F - 3  (source 842-843)
        if F >= G { F = F - 3; }

        // Random-walk drift, threshold +/-8deg = 1456 BAM, step 3deg = 546 BAM.
        if D < -1456 {
            D = D + rand(546);                 // %RANDF * 3deg
        } else if D > 1456 {
            D = D - rand(546);                 // %RANDF * 3deg
        } else {
            D = D + rand(1092) - 546;          // %RANDF2 * 3deg
        }

        // unless ($F > 60) wait($F); else wait(60)  (source 855-859)
        var w: int = F;
        if F > 60 { w = 60; }
        var rem: int = HELPER_STOP - t;
        if w > rem { w = rem; }
        wait(w);
        t = t + w;
    }
}

// BossCard1 entry (source 724-767), starting from Boss public position (0,128).
async sub boss_pattern() {
    wait(OPENING_BUFFER);          // card-frame opening buffer; source frame 0 next

    // Source 735-737: zero velocity / cancel stale interpolation. movePosTime
    // frames<=0 only cancels interpolation, so do not teleport to (0,0).
    move_vel_xy(0, 0fx, 0fx, EASE_LINEAR);

    // Source 747: movePosTime(60, 4, 0, 144)
    move_to(60, 0fx, 144fx, EASE_QUAD_OUT);
    // Source 748 moveLimit(0,128,280,64) -> x[-140,140], y[96,160]; the boss
    // stays at (0,144) afterwards, so the limit is never binding.

    wait(60);                      // source +60: presentation only
    wait(90);                      // source +90:. //150 spawn below

    spawn boss_card1_at();         // source 759 @BossCard1_at() async
    wait(180);                     // source 760
    loop { wait(120); }            // source 980/960 idle loop until spell end
}

async sub boss_main() {
    set_invuln(65535);
    set_hitbox(24fx);              // source Boss:27 setHitbox(48,48) -> r24
    set_hurtbox(24fx);             // source Boss:28 setHurtbox(48,48) -> r24

    // Source 741 setInterrupt(0,0,2700,"Boss2") + 743/745 spell(84,2700,...).
    spell_begin(0, 84, boss_pattern, TIME_LIMIT, 500000, 0, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 128fx, 3000, 0, 0, 0, boss_main);
    loop { wait(600); }
}
